    /// <summary>
    /// Returns information about the recent locations of chat members that were sent to the chat. Returns up to 1 location message per user
    /// </summary>
    public Task<TdLib.TdApi.Objects.Messages> SearchChatRecentLocationMessagesAsync(long chatId = default, int limit = default)
    {

           using var activity =  StartCallActivity("SearchChatRecentLocationMessagesAsync", typeof(SearchChatRecentLocationMessages).FullName ?? "SearchChatRecentLocationMessagesAsync");

           try
           {
             return client.SearchChatRecentLocationMessagesAsync(chatId, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
